package compute

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	computepb "myapp/gen/compute/v1"
	"myapp/driver"
)

type ComputeServer struct {
	computepb.UnimplementedComputeServiceServer
	CloudDriver driver.VirtualMachineDriver
}

func (s *ComputeServer) TerminateVM(ctx context.Context, req *computepb.TerminateVMRequest) (*computepb.TerminateVMResponse, error) {
	// BOLA: Trusts projectId and vmId from RPC request message without matching against caller's authorized project.
	err := s.CloudDriver.Delete(ctx, req.GetProjectId(), req.GetVmId())
	if err != nil {
		return nil, status.Errorf(codes.Internal, "VM termination failed: %v", err)
	}

	return &computepb.TerminateVMResponse{
		Terminated: true,
	}, nil
}

corrected_code:
package compute

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	computepb "myapp/gen/compute/v1"
	"myapp/auth"
	"myapp/driver"
)

type ComputeServer struct {
	computepb.UnimplementedComputeServiceServer
	CloudDriver driver.VirtualMachineDriver
}

func (s *ComputeServer) TerminateVM(ctx context.Context, req *computepb.TerminateVMRequest) (*computepb.TerminateVMResponse, error) {
	claims, ok := auth.ClaimsFromContext(ctx)
	if !ok {
		return nil, status.Error(codes.Unauthenticated, "Unauthenticated gRPC request")
	}

	if claims.ProjectID != req.GetProjectId() {
		return nil, status.Error(codes.PermissionDenied, "Caller not authorized for specified project")
	}

	err := s.CloudDriver.Delete(ctx, claims.ProjectID, req.GetVmId())
	if err != nil {
		return nil, status.Errorf(codes.Internal, "VM termination failed: %v", err)
	}

	return &computepb.TerminateVMResponse{
		Terminated: true,
	}, nil
}
